<template>
  <MarketplaceLayout><main class="market-container market-page community-page"><div class="discussion">
    <RouterLink to="/community">Về cộng đồng</RouterLink><ResourceState v-if="loading || error" resource="bài viết" :loading="loading" :error="Boolean(error)" @retry="load"/>
    <template v-else-if="post"><article><h1>{{ post.title }}</h1><p class="community-topic">{{ topics[post.topic] }}</p><p class="discussion-meta">{{ post.authorName }} · <time :datetime="post.createdAt">{{ date(post.createdAt) }}</time></p><p class="community-post-body">{{ post.body }}</p><div v-if="owns(post)" class="discussion-actions"><RouterLink :to="'/community/posts/'+post.id+'/edit'">Chỉnh sửa bài viết</RouterLink><button class="text-link" :disabled="busy" @click="removePost">{{ isAdmin?'Gỡ bài viết':'Xóa bài viết của tôi' }}</button></div></article>
      <section aria-labelledby="comments-title"><h2 id="comments-title">Thảo luận</h2><ResourceState v-if="commentLoading || commentError" resource="bình luận" :loading="commentLoading" :error="Boolean(commentError)" @retry="loadComments"/><template v-else><p v-if="!comments.content.length" class="discussion-empty">Chưa có bình luận. Cùng trao đổi thêm về chủ đề này.</p><article v-for="c in comments.content" :key="c.id" class="discussion-entry"><header><strong>{{ c.authorName }}</strong><time :datetime="c.createdAt">{{ date(c.createdAt) }}</time></header><form v-if="editing===c.id" @submit.prevent="editComment(c)"><label :for="'edit-comment-'+c.id">Chỉnh sửa bình luận</label><textarea :id="'edit-comment-'+c.id" v-model="editBody" required maxlength="3000" rows="4"/><div class="discussion-actions"><button class="button button-outline" :disabled="busy">Lưu bình luận</button><button type="button" class="button button-outline" :disabled="busy" @click="editing=null">Hủy</button></div></form><p v-else class="discussion-text">{{ c.body }}</p><div v-if="owns(c)&&editing!==c.id" class="discussion-actions"><button class="text-link" :disabled="busy" @click="editing=c.id;editBody=c.body">Sửa bình luận</button><button class="text-link" :disabled="busy" @click="removeComment(c)">{{ isAdmin?'Gỡ bình luận':'Xóa bình luận' }}</button></div></article><nav v-if="comments.totalPages>1" aria-label="Phân trang bình luận" class="discussion-pagination"><button class="button button-outline" :disabled="page===0||busy" @click="page--;loadComments()">Trước</button><span>Trang {{ page+1 }} / {{ comments.totalPages }}</span><button class="button button-outline" :disabled="page+1>=comments.totalPages||busy" @click="page++;loadComments()">Sau</button></nav></template>
        <p v-if="submitError" role="alert">{{ submitError }}</p><p v-if="message" role="status">{{ message }}</p><form v-if="isAuthenticated" @submit.prevent="sendComment"><label for="comment-body">Bình luận của bạn</label><textarea id="comment-body" v-model="body" maxlength="3000" required rows="4"/><button class="button button-primary" :disabled="busy||!body.trim()">{{ busy?'Đang gửi…':'Gửi bình luận' }}</button></form><p v-else><RouterLink :to="{path:'/login',query:{redirect:route.fullPath}}">Đăng nhập để bình luận</RouterLink></p>
      </section>
    </template>
  </div></main></MarketplaceLayout>
</template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import MarketplaceLayout from '../../../layouts/MarketplaceLayout.vue';import ResourceState from '../../../components/marketplace/ResourceState.vue';import {marketplaceRequest as request} from '../../../services/marketplace.js';import {topics,date} from '../../../services/discussions.js';import {useAuth} from '../../../composables/useAuth.js';import '../../../css/discussions.css';
const route=useRoute(),router=useRouter(),{user,isAuthenticated,isAdmin}=useAuth(),post=ref(null),comments=ref({content:[],totalPages:0}),loading=ref(false),error=ref(''),commentLoading=ref(false),commentError=ref(''),submitError=ref(''),message=ref(''),busy=ref(false),body=ref(''),page=ref(0),editing=ref(null),editBody=ref('');let generation=0,commentGeneration=0;
const owns=item=>isAuthenticated.value&&(isAdmin.value||item.authorId===user.value?.id);
async function load(){const ticket=++generation;post.value=null;loading.value=true;error.value='';body.value='';page.value=0;editing.value=null;submitError.value='';message.value='';try{const result=await request('/community/posts/'+encodeURIComponent(route.params.id));if(ticket===generation){post.value=result;await loadComments();}}catch(e){if(ticket===generation)error.value=e.message;}finally{if(ticket===generation)loading.value=false;}}
async function loadComments(){const ticket=++commentGeneration,parent=generation;commentLoading.value=true;commentError.value='';try{const result=await request('/community/posts/'+encodeURIComponent(route.params.id)+'/comments?page='+page.value);if(ticket===commentGeneration&&parent===generation)comments.value=result;}catch(e){if(ticket===commentGeneration&&parent===generation)commentError.value=e.message;}finally{if(ticket===commentGeneration&&parent===generation)commentLoading.value=false;}}
async function mutate(action,success){if(busy.value)return;busy.value=true;submitError.value='';message.value='';const ticket=generation;try{await action();if(ticket!==generation)return;message.value=success;await loadComments();}catch(e){if(ticket===generation)submitError.value=e.message;}finally{busy.value=false;}}
function sendComment(){return mutate(async()=>{await request('/account/community/posts/'+post.value.id+'/comments','POST',{body:body.value});body.value='';page.value=Math.floor(comments.value.totalElements/10);},'Đã gửi bình luận.');}
function editComment(c){return mutate(async()=>{await request('/account/community/comments/'+c.id,'PUT',{body:editBody.value,revision:c.revision});editing.value=null;},'Đã lưu bình luận.');}
function removeComment(c){return mutate(()=>request('/account/community/comments/'+c.id+'?revision='+c.revision,'DELETE'),'Đã xóa bình luận.');}
async function removePost(){if(busy.value)return;busy.value=true;try{await request('/account/community/posts/'+post.value.id+'?revision='+post.value.revision,'DELETE');await router.push('/community');}catch(e){submitError.value=e.message;}finally{busy.value=false;}}
watch(()=>route.params.id,load,{immediate:true});onBeforeUnmount(()=>{generation++;commentGeneration++;});
</script>
